CREATE FUNCTION public.perform_car_transfer(_car uuid,_target uuid,_confirm boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.cars; BEGIN SELECT * INTO v FROM public.cars WHERE id=_car FOR UPDATE; IF _confirm THEN IF NOT public.branch_manager_access(v.transfer_to) OR v.status<>'In Transit' OR v.transfer_to IS NULL THEN RAISE EXCEPTION 'Invalid transfer confirmation'; END IF; UPDATE public.cars SET branch_id=transfer_to,transfer_to=NULL,status='Available',updated_at=now() WHERE id=_car; ELSE IF NOT public.branch_manager_access(v.branch_id) OR v.status<>'Available' OR _target IS NULL OR _target=v.branch_id THEN RAISE EXCEPTION 'Invalid transfer request'; END IF; UPDATE public.cars SET transfer_to=_target,status='In Transit',updated_at=now() WHERE id=_car; END IF; END $$;
REVOKE ALL ON FUNCTION public.perform_car_transfer(uuid,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.perform_car_transfer(uuid,uuid,boolean) TO authenticated;
CREATE FUNCTION public.validate_enquiry_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.employee_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.employees WHERE id=NEW.employee_id AND branch_id=NEW.branch_id) THEN RAISE EXCEPTION 'Employee must belong to the enquiry branch'; END IF; IF NEW.car_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.cars WHERE id=NEW.car_id AND branch_id=NEW.branch_id) THEN RAISE EXCEPTION 'Car must belong to the enquiry branch'; END IF; IF NEW.appointment_date IS NOT NULL AND (TG_OP='INSERT' OR NEW.appointment_date IS DISTINCT FROM OLD.appointment_date) AND NEW.appointment_date<now() THEN RAISE EXCEPTION 'Appointment must be in the future'; END IF; IF NEW.enquiry_type='Booking Request' AND NEW.status IN ('Confirmed','Completed') AND NOT EXISTS(SELECT 1 FROM public.cars WHERE id=NEW.car_id AND status IN ('Available','Reserved')) THEN RAISE EXCEPTION 'Booking requires an eligible car'; END IF; IF TG_OP='UPDATE' AND NEW.procurement_decision IS DISTINCT FROM OLD.procurement_decision THEN IF NOT public.branch_manager_access(NEW.branch_id) THEN RAISE EXCEPTION 'Only managers may decide procurement'; END IF; NEW.decision_at=now(); SELECT id INTO NEW.decision_by FROM public.employees WHERE auth_user_id=auth.uid() LIMIT 1; END IF; IF TG_OP='INSERT' AND NOT public.branch_manager_access(NEW.branch_id) AND NEW.procurement_decision<>'Pending' THEN RAISE EXCEPTION 'Unauthorized decision'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER enquiry_integrity BEFORE INSERT OR UPDATE ON public.enquiries FOR EACH ROW EXECUTE FUNCTION public.validate_enquiry_update();
CREATE FUNCTION public.guard_car_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF pg_trigger_depth()>1 THEN RETURN NEW; END IF; IF EXISTS(SELECT 1 FROM public.sales WHERE car_id=OLD.id AND status<>'Cancelled') AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.branch_id IS DISTINCT FROM OLD.branch_id OR NEW.transfer_to IS DISTINCT FROM OLD.transfer_to) THEN RAISE EXCEPTION 'Car is linked to an active sale'; END IF; RETURN NEW; END $$;
CREATE TRIGGER car_integrity BEFORE UPDATE ON public.cars FOR EACH ROW EXECUTE FUNCTION public.guard_car_change();
CREATE FUNCTION public.validate_purchase() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.employees WHERE id=NEW.employee_id AND branch_id=NEW.branch_id) THEN RAISE EXCEPTION 'Purchase employee must belong to the branch'; END IF; IF TG_OP='UPDATE' AND (NEW.car_id<>OLD.car_id OR NEW.branch_id<>OLD.branch_id) THEN RAISE EXCEPTION 'Purchase identity cannot be changed'; END IF; IF TG_OP='INSERT' AND NEW.status<>'Pending Approval' THEN RAISE EXCEPTION 'New purchases require approval'; END IF; IF TG_OP='UPDATE' AND NEW.status<>OLD.status AND NOT ((OLD.status='Pending Approval' AND NEW.status IN ('Approved','Cancelled')) OR (OLD.status='Approved' AND NEW.status IN ('Ordered','Cancelled')) OR (OLD.status='Ordered' AND NEW.status IN ('Received','Cancelled'))) THEN RAISE EXCEPTION 'Invalid purchase transition'; END IF; IF NOT EXISTS(SELECT 1 FROM public.cars WHERE id=NEW.car_id AND (status IN ('Unassigned','In Transit') OR (TG_OP='UPDATE' AND OLD.status='Received'))) THEN RAISE EXCEPTION 'Purchase requires an unassigned or in-transit car'; END IF; RETURN NEW; END $$;
CREATE TRIGGER purchase_integrity BEFORE INSERT OR UPDATE ON public.purchases FOR EACH ROW EXECUTE FUNCTION public.validate_purchase();
CREATE POLICY cars_transfer_visible ON public.cars FOR UPDATE TO authenticated USING(public.branch_manager_access(transfer_to)) WITH CHECK(public.branch_manager_access(branch_id));
REVOKE DELETE ON public.sales,public.purchases FROM authenticated;
